dataModel:
public enum PartyState { Forming, Travelling, Working, Waiting, Returning, Disbanded }
public sealed class Party {
  public int Id; public string Owner;      // "player" or faction id
  public List<int> Members = new();        // survivor ids
  public int Tile; public int HomeBaseId;
  public List<int> Path = new(); public int PathIdx; public float Progress; // 0..1 into next tile
  public Dictionary<string, float> Supplies = new(); // "food", "water"
  public Inventory Cargo = new();
  public PartyState State;
}

public enum TravelMode { Foot, Bike, Vehicle }
public interface IGraph<T> {
  IEnumerable<T> Neighbours(T n);
  float Cost(T from, T to);       // float.PositiveInfinity = blocked
  float Heuristic(T a, T goal);   // must never overestimate
}
public sealed record PathResult(IReadOnlyList<int> Tiles, float Hours);
public sealed record TerrainDef(string Id, float WalkCost, float VehicleCost, string ArtKey);

public enum TileVis : byte { Unknown, Remembered, Visible }
public sealed record TileSnapshot(int Hour, string Terrain, int? SiteId, int DeadBand);
public sealed class Knowledge {
  public TileSnapshot?[] Seen;     // index = tile id
  public BitArray LiveNow;          // recomputed each hour, not saved
  public HashSet<int> FoundSites = new();
}

public sealed record PoiKindDef(string Id, string Name, string ArtKey, string[] Terrains,
  int Danger, string LootTable, string BuildingTemplate);
public sealed class Poi {
  public int Id; public int Tile; public string Kind;
  public bool Hidden; public float LootLeft = 1f;
  public List<int> VisitHours = new();
}

public enum LandClass { Centre, City, Suburb, Town, Highway, Rural, Coast, Scenic }
public sealed record DeadCapDef(LandClass Class, int Cap, float Fill);
public sealed class DeadPopulation {
  public int[] OpenDead;                 // by tile id
  public Dictionary<int, int> PoiDead = new(); // by poi id
  public int TileDead(int tile, IEnumerable<int> poiIds) => OpenDead[tile] + poiIds.Sum(p => PoiDead.GetValueOrDefault(p));
}

public sealed record TravelEventDef(string Id, float Weight, EventCond When,
  string TitleKey, string TextKey, ChoiceDef[] Choices);
public sealed record EventCond(string[]? Terrains, int? Season, bool? Night, int MinDead = 0);
public sealed record ChoiceDef(string LabelKey, OutcomeDef[] Outcomes, float? SkillCheck = null);
public sealed record OutcomeDef(string Op, string? Arg, float Amount);

public sealed record WorldSizeDef(string Id, int W, int H, int AiGroups, int Towns);
public sealed class WorldGenParams { public int Seed; public string Size; public float Water, Forest, Hills; }
public sealed class Settlement { public int Id; public string Name; public int Tile; public SettlementKind Kind; public List<int> Tiles = new(); }
public enum SettlementKind { City, Suburb, Town }
public sealed class Road { public List<int> Tiles = new(); public bool Highway; }

public enum Wx { Clear, Rain, Storm, Fog, Heat, Snow, Blizzard }
public sealed class Front { public Wx Type; public float X, Y, Dx, Dy, Radius; public int EndHour; }
public sealed class WeatherState {
  public List<DayWeather> Days = new(); public List<Front> Fronts = new();
  public byte[] Mud, Snow;              // per tile
  public PondState[] Ponds;
}
public readonly record struct PondState(int Day, int Dry, bool Ice);

public sealed record VehicleTypeDef(string Id, string Name, float Tank, float PayloadKg, int Seats,
  float Speed = 1, float FuelMult = 1, float Offroad = 1, bool Loud = false, string ArtKey = "");
public sealed class Vehicle {
  public int Id; public string Type; public float Fuel; public float Condition; // 0..1
  public int? PartyId; public int? ParkedTile; public int? BaseId;
  public Inventory Cargo = new();
}

public enum OrderType { Move, LookAround, Scavenge, Rest, Gather, Wait, ReturnHome }
public sealed record Order(OrderType Type, int? Tile, int? PoiId, float Hours);
public sealed class Plan {
  public Queue<Order> Steps = new();
  public float ReturnIfHealthBelow = 0; public float ReturnIfFoodDaysBelow = 0; public bool ReturnIfFull;
}
public sealed record TripTemplate(string Name, string[] Roles, string? VehicleType, Dictionary<string,float> Supplies, Order[] Steps);

public sealed record LoadBand(string Key, float UpToKg, float Slow, float Eat);
public sealed class Hold {
  public Dictionary<string, float> Pocket = new(), Pack = new(), Hands = new();
  public int? CarryingPieceId; public int? TetheredTo; // another survivor's id
}
public enum CarryClass { One, Two, Fixed }

public sealed record HeatStage(string Name, int Min, float Fight, string DescKey);
public sealed class ScavengeRun {
  public int PartyId, PoiId; public int Hours; public float Heat;
  public Inventory Found = new();
}

public sealed record ThreatStamp(int Hour, int DeadEst, int RaidersEst, float Err, string Source);
public sealed record Rumour(int Tile, int Radius, int ExpiresDay, string Source);
public sealed class Marker { public int Tile; public string Type; public int LastSeenHour; public string? Note; }

public sealed record NightMarchRules(int From = 22, int To = 6, float Events = 1.8f, float Conflict = 1.6f);
public sealed class WandererGroup {
  public int Id; public WandererKind Kind; public int Tile;
  public List<int> Members = new(); public float Mood;
}
public enum WandererKind { Neutral, Aggressive, Military }

public sealed class CityCrawl {
  public int PartyId, SettlementId; public int Radius;
  public Block[] Blocks; public int Current; public float Alert;
}
public sealed class Block { public int Q, R, Level; public List<int> Places = new(); public float Trail; public bool Visited; }
public enum CrawlPhase { Entering, OnBlock, InPlace, Leaving, Out }

public sealed record CrashKindDef(string Id, string LootTable, int Danger, string ArtKey);
public sealed class CrashSite {
  public int Id; public string Kind; public int WreckTile; public int DayFell;
  public int CircleCentre; public int CircleRadius; public HashSet<int> Cleared = new();
  public bool Found; public string? ClaimedBy;
}
public enum CampState { Abandoned, Overrun, RaiderCamp }
